const CACHE='hocco-message-shell-v23';
const SHELL=['/','/index.html','/cliente/','/cliente/index.html','/cliente/entry.mjs','/ir-alem/','/ir-alem/index.html','/ir-alem/app.mjs','/style.css','/app.mjs','/opening.mjs','/support.mjs','/pwa.mjs','/config.mjs','/pix.mjs','/policies.mjs','/manifest.webmanifest','/assets/figurantes-3d.webp','/assets/hocco-message-icon.svg','/assets/hocco-message-192.png','/assets/hocco-message-512.png','/assets/hocco-message-video.mp4','/assets/comunidade-hocco.webp'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(/^\/(?:controle|equipe)(?:\/|$)/.test(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const clone=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,clone))}return response}).catch(()=>caches.match(event.request).then(response=>response||caches.match('/index.html'))))});
